L["The Shoulder Cam doesn't work with the gamepad UI yet. While it's on, the game keeps your character in the middle of the screen, so the Shoulder Cam waits behind you and comes back by itself when you turn the gamepad UI off (Options > Gamepad (Beta) > Enable Gamepad UI)."] = "A Câmera de ombro ainda não funciona com a interface de controle. Enquanto ela está ligada, o jogo mantém seu personagem no meio da tela, então a Câmera de ombro espera atrás de você e volta sozinha quando você desliga a interface de controle (Opções > Controle (Beta) > Ativar interface de controle)."
L["Calibrating my camera, please ignore this line for a moment: I'm measuring where my character sits on the screen as the camera moves over my shoulder. Thanks for your patience!"] = "Calibrando minha câmera, por favor ignorem esta linha por um momento: estou medindo onde meu personagem fica na tela enquanto a câmera vai para cima do meu ombro. Obrigado pela paciência!"
