L["One of the game's full-screen effects closing in as you weaken."] = "Um dos efeitos de tela cheia do jogo se fechando enquanto você enfraquece."
L["Turns Vitals Vision on or off."] = "Ativa ou desativa o Vitals Vision."
L["The screen's edges close in as your health drops."] = "As bordas da tela se fecham conforme a sua vida cai."
L["How strong the edges are out of a fight."] = "A força das bordas fora de combate."
L["Ramp up"] = "Aceleração"
L["Higher makes the edges close in slowly at first, then faster."] = "Mais alto faz as bordas se fecharem devagar no início, depois mais rápido."
