L["Game setting: |cff00ff00flash on|r"] = "Opção do jogo: |cff00ff00piscar ativado|r"
L["How fast the edges close in when your health drops."] = "A velocidade com que as bordas se fecham quando a sua vida cai."
L["How fast the edges lift when you're healed."] = "A velocidade com que as bordas se abrem quando você é curado."
