L["CineMode hides the action bars: pick which show, and when."] = "O CineMode oculta as barras de ações: escolha quais aparecem, e quando."
L["CineMode hides your buffs and debuffs: pick when they show."] = "O CineMode oculta os seus bônus e penalidades: escolha quando eles aparecem."
L["CineMode hides timers and meters: pick which show, and when."] = "O CineMode oculta cronômetros e medidores: escolha quais aparecem, e quando."
