-- Options.lua
L["Pick Always, < 100%, < 100% Calm or Off, or scroll over the box for other percentages."] = "Escolha Sempre, < 100%, < 100% Calma ou Desativado, ou role o mouse sobre a caixa para outras porcentagens."
L["Pick Always, < 100% or Off, or scroll over the box for other percentages."] = "Escolha Sempre, < 100% ou Desativado, ou role o mouse sobre a caixa para outras porcentagens."
L["Turns this page on or off, same as right-clicking its icon."] = "Ativa ou desativa esta página, igual a clicar com o botão direito no ícone dela."
L["Put this page's settings back to your profile's defaults?"] = "Voltar as configurações desta página ao padrão do seu perfil?"
L["Put these settings back to your profile's defaults?"] = "Voltar estas configurações ao padrão do seu perfil?"
L["|cff808080Searching...|r"] = "|cff808080Procurando...|r"
L["Allow offscreen nameplates in CineMode"] = "Permitir placas fora da tela no CineMode"
L["Keeps plates for people behind you, so Heal Vision and Emote Vision see them too."] = "Mantém as placas de quem está atrás de você, para o Heal Vision e o Emote Vision também verem essas pessoas."
L["Only where Heal Vision or Emote Vision use them."] = "Só onde o Heal Vision ou o Emote Vision as usam."
L["All through CineMode."] = "Durante todo o CineMode."
L["Cinematic never turns them on."] = "O Cinematic nunca as ativa."
L["CineMode turns on by itself between fights and fades the UI."] = "O CineMode entra sozinho entre as lutas e esmaece a interface."
L["Walking or riding around brings the UI back."] = "Andar a pé ou montado traz a interface de volta."
L["Use a Show in row instead"] = "Usar uma linha Mostrar em"
L["The row below picks where CineMode exits, in place of the boxes above."] = "A linha abaixo escolhe onde o CineMode sai, no lugar das caixas acima."
L["Keeps CineMode off everywhere."] = "Mantém o CineMode desligado em todo lugar."
L["Sweeps turn the other way."] = "As varreduras giram para o outro lado."
L["Each time, the camera picks clockwise or counterclockwise at random."] = "A cada vez, a câmera escolhe ao acaso o sentido horário ou anti-horário."
L["Put this camera's settings back to your profile's defaults?"] = "Voltar as configurações desta câmera ao padrão do seu perfil?"
L["Now and then the camera turns around to look back past you."] = "De vez em quando a câmera se vira para olhar para trás de você."
L["How far the camera turns around, where 180 looks straight back at you."] = "O quanto a câmera se vira; em 180 ela olha direto para você."
L["How long the turn around takes, speeding up and slowing down."] = "Quanto tempo a virada leva, acelerando e desacelerando."
L["As you land, the camera zooms back to the zoom you had at takeoff."] = "Ao pousar, a câmera volta ao zoom que você tinha na decolagem."
L["The camera sways slowly from side to side around where it started, pausing between moves."] = "A câmera balança devagar de um lado para o outro em volta de onde começou, com pausas entre os movimentos."
L["Once it has turned halfway around, the camera sways slowly from side to side."] = "Depois de dar meia-volta, a câmera balança devagar de um lado para o outro."
L["When you /stare at the view, the camera sways very slightly from where it is."] = "Quando você usa /stare para contemplar a vista, a câmera balança bem de leve de onde está."
L["The camera sways very slightly from side to side."] = "A câmera balança bem de leve de um lado para o outro."
L["While you fish, the camera sways a little and keeps your bobber in view."] = "Enquanto você pesca, a câmera balança um pouco e mantém a boia à vista."
L["While you auto-walk, the camera drifts slowly along with you."] = "Enquanto você anda automaticamente, a câmera desliza devagar junto com você."
L["Each death, the camera picks clockwise or counterclockwise at random."] = "A cada morte, a câmera escolhe ao acaso o sentido horário ou anti-horário."
L["The camera zooms in to this distance if you're farther out."] = "A câmera se aproxima até esta distância se você estiver mais longe."
L["Which side of you the camera moves to."] = "Para qual lado seu a câmera vai."
L["The camera turns to the side as it zooms in, then tilts down."] = "A câmera vira para o lado enquanto se aproxima, depois se inclina para baixo."
L["How fast the spin speeds up after the first half turn."] = "O quanto o giro acelera depois da primeira meia-volta."
L["As it turns, the camera also drops toward the ground. Negative values raise it instead."] = "Enquanto gira, a câmera também desce em direção ao chão. Valores negativos a fazem subir."
L["The camera starts zooming in when the cast starts, and is still zooming in as you leave."] = "A câmera começa a se aproximar quando o lançamento começa, e ainda está se aproximando quando você parte."
L["How fast the camera zooms back out to your own distance if you cancel the cast."] = "O quão rápido a câmera volta à sua distância se você cancelar o lançamento."
L["Load Atmosphere"] = "Carregar Atmosfera"
L["Unticked, Atmosphere doesn't load at all (takes a reload)."] = "Desmarcado, a Atmosfera nem carrega (precisa recarregar)."
L["Tick it and reload to bring every Atmosphere page back."] = "Marque e recarregue para trazer de volta todas as páginas de Atmosfera."
L["Turn off to keep Atmosphere from loading at all."] = "Desative para a Atmosfera nem carregar."
L["Atmosphere isn't loaded: no tint, letterbox, haze, Graphics Boost or music runs, and their pages are gone."] = "A Atmosfera não está carregada: nada de tonalidade, faixas, névoa, Melhoria gráfica ou música, e as páginas deles somem."
L["How the game world looks in CineMode: vignette, inn glow and depth of field."] = "Como o mundo do jogo fica no CineMode: vinheta, brilho de estalagem e profundidade de campo."
L["Haze"] = "Névoa"
L["Darkens the edges of the screen."] = "Escurece as bordas da tela."
L["Shows the vignette for a few seconds, in CineMode or not."] = "Mostra a vinheta por alguns segundos, no CineMode ou não."
L["A warm firelight glow, brightest low on the screen."] = "Um brilho quente de fogueira, mais forte na parte de baixo da tela."
L["Shows the glow for a few seconds, in CineMode or not."] = "Mostra o brilho por alguns segundos, no CineMode ou não."
L["Haze strength"] = "Intensidade da névoa"
L["A light haze around the edges of the screen."] = "Uma névoa leve em volta das bordas da tela."
L["Shows the haze at this strength for a few seconds, in CineMode or not."] = "Mostra a névoa nesta intensidade por alguns segundos, no CineMode ou não."
L["How they look"] = "Como ficam"
