-- Atmosphere/LowHealth.lua
L["That isn't the whole thing. Copy it again, all of it."] = "Isso não está completo. Copie de novo, tudo."
L["At what health the edges close in, and how fast."] = "Com quanta vida as bordas se fecham, e o quão rápido."
L["The color of a big hit's flash, and the color the world fades to."] = "A cor do lampejo de um golpe forte, e a cor para a qual o mundo esmaece."
L["This theme's heartbeat speed, relative to Beats a minute above. A creeping theme beats slower."] = "A velocidade dos batimentos deste tema, em relação a Batimentos por minuto acima. Um tema que se arrasta bate mais devagar."
L["How much this theme throbs, relative to Throb above."] = "O quanto este tema pulsa, em relação a Pulsação acima."
L["The theme's art that spreads in from the edges."] = "A arte do tema que avança a partir das bordas."
L["The glow around the art, added as light. This is Glow's only color."] = "O brilho em volta da arte, somado como luz. Esta é a única cor do Brilho."
L["How strong the glow is compared to the art."] = "O quanto o brilho é forte em relação à arte."
L["The theme's art (blood, smoke, a glow) that spreads in from the edges as they close in."] = "A arte do tema (sangue, fumaça, um brilho) que avança a partir das bordas conforme elas se fecham."
L["How many appear per minute at full strength. A big hit adds a few more."] = "Quantos aparecem por minuto na intensidade máxima. Um golpe forte adiciona mais alguns."
L["How big they are compared to normal."] = "O tamanho deles em relação ao normal."
L["How strong it is at full, multiplied by the art's opacity."] = "A intensidade no máximo, multiplicada pela opacidade da arte."
L["Overall strength, reach and brightness, plus the shadow, the heartbeat and big hits."] = "Intensidade geral, alcance e brilho, além da sombra, dos batimentos e dos golpes fortes."
L["How the screen looks as your mana runs out."] = "Como a tela fica conforme a sua mana acaba."
L["As your health drops, the edges of the screen close in."] = "Conforme a sua vida cai, as bordas da tela se fecham."
L["Shows everywhere, so the other columns don't change anything."] = "Aparece em todo lugar, então as outras colunas não mudam nada."
L["The edges start closing in when your health drops below this."] = "As bordas começam a se fechar quando a sua vida cai abaixo disto."
L["The edges are all the way in when your health drops to this. Keep it below Starts."] = "As bordas se fecham por completo quando a sua vida cai a isto. Mantenha abaixo de Começa."
L["How much of your health one hit has to take to count as a big hit."] = "Quanto da sua vida um golpe tem que tirar para contar como golpe forte."
L["As your mana runs out, the screen drains. Right-click the tab to turn it on."] = "Conforme a sua mana acaba, a tela perde a cor. Clique com o botão direito na aba para ativar."

