L["How strong it is out of a fight."] = "A intensidade fora de combate."
L["Shows your mana running out on the screen."] = "Mostra na tela a sua mana acabando."
L["This character doesn't use mana, so nothing shows."] = "Este personagem não usa mana, então nada aparece."
L["Drained"] = "Desbotado"
L["Gray-blue: the world's color drains away."] = "Cinza-azulado: a cor do mundo vai sumindo."
L["Cold"] = "Frio"
L["A cold, deep blue."] = "Um azul frio e profundo."
L["A dim, gray-violet dusk."] = "Um anoitecer escuro, cinza-violeta."
L["How strong the veil and the edges are when your mana is out."] = "A intensidade do véu e das bordas quando a sua mana acaba."
L["Dark edges"] = "Bordas escuras"
L["Dark edges close in as your mana runs out."] = "Bordas escuras se fecham conforme a sua mana acaba."
L["How far in from the screen's edges they come."] = "O quanto elas avançam a partir das bordas da tela."
L["Shows your mana running out in the preview and on screen."] = "Mostra a sua mana acabando na pré-visualização e na tela."

