-- Atmosphere/Tint.lua
L["Warm brownish yellow, like an old photo. The world can't be fully desaturated."] = "Amarelo amarronzado e quente, como uma foto antiga. O mundo não pode perder a cor por completo."
L["A warm haze over everything."] = "Uma névoa quente sobre tudo."

-- Camera/CameraManager.lua
L["Right-click to copy it, or to rename, describe, change the icon of or delete one of yours."] = "Clique com o botão direito para copiá-la, ou para renomear, descrever, trocar o ícone ou excluir uma das suas."
