-- Camera/CameraScriptsPage.lua
L["Runs when the camera ends, whatever ends it (its stop rules say what does). Every camera has one and it can't be removed. Pick it and add steps to put them inside."] = "Roda quando a câmera termina, seja o que for que a termine (as regras de parada dizem o quê). Toda câmera tem um e ele não pode ser removido. Escolha-o e adicione passos para colocá-los dentro."
L["Lets scenes play your scripts, and lets our cameras use your changes to their scripts."] = "Deixa as cenas tocarem os seus roteiros, e deixa as nossas câmeras usarem as suas mudanças nos roteiros delas."
L["This script as text to share with friends."] = "Este roteiro como texto para compartilhar com amigos."
L["A haze around the edges of the screen while this camera runs. Set to 0 to turn it off."] = "Uma névoa em volta das bordas da tela enquanto esta câmera roda. Ponha em 0 para desativar."
L["A built-in camera you've changed. Reset puts ours back."] = "Uma câmera embutida que você mudou. Redefinir traz a nossa de volta."
L["A built-in camera, made from your settings. Any change you make saves it as your own."] = "Uma câmera embutida, feita com as suas configurações. Qualquer mudança a salva como sua."

-- Camera/CameraTriggerEditor.lua
L["Another trigger for this scene. Any one of its triggers starts it."] = "Outro gatilho para esta cena. Qualquer um dos gatilhos dela a inicia."
L["Turns CineMode on while its camera runs, if Start in CineMode is off."] = "Liga o CineMode enquanto a câmera dela roda, se Começar no CineMode estiver desativado."

-- Camera/ShotsPage.lua
L["Copies text you can send a friend, who adds this shot with Import here or on their Scenes page."] = "Copia um texto que você pode mandar a um amigo, que adiciona esta tomada com Importar aqui ou na página Cenas dele."
L["The camera whose moves this shot uses."] = "A câmera cujos movimentos esta tomada usa."
L["Clears this shot's numbers so they go back to its camera's own settings."] = "Apaga os números desta tomada para voltarem às configurações da câmera dela."

-- Camera/ShoulderCalibrate.lua
L["Stops using this measurement and goes back to the built-in size."] = "Para de usar esta medida e volta ao tamanho embutido."

-- Camera/ShoulderCam.lua
L["Another addon (DynamicCam) is running a shoulder camera, so the Shoulder Cam stays off."] = "Outro addon (DynamicCam) está rodando uma câmera de ombro, então a Câmera de ombro fica desligada."
L["Shoulder Cam uses some experimental Blizzard features, as well as some hacks to fill in the gaps."] = "A Câmera de ombro usa alguns recursos experimentais da Blizzard, além de alguns truques para tapar os buracos."
L["Which frames slide with you while the camera is over your shoulder."] = "Quais quadros deslizam com você enquanto a câmera está sobre o seu ombro."
L["Which of Cinematic's cameras keep the Shoulder Cam on while they play."] = "Quais câmeras do Cinematic mantêm a Câmera de ombro ligada enquanto tocam."
L["Over your shoulder everywhere, so the other columns don't matter."] = "Sobre o ombro em todo lugar, então as outras colunas não importam."
L["How far from the middle you sit when zoomed out. Set it lower than Spot on screen to keep the camera from catching on walls, which only happens zoomed out."] = "O quão longe do meio você fica com o zoom afastado. Ponha abaixo de Posição na tela para a câmera não enroscar nas paredes, o que só acontece com o zoom afastado."
L["The camera distance where you reach Spot zoomed out. Between 5 yards and this distance, you slide from Spot on screen to Spot zoomed out."] = "A distância da câmera em que você chega à Posição com zoom afastado. Entre 5 metros e esta distância, você desliza da Posição na tela para a Posição com zoom afastado."
L["Keep the shoulder when selecting yourself"] = "Manter o ombro ao se selecionar"
L["Selecting yourself clears your target instead, so the camera stays over your shoulder. Heals and buffs still land on you."] = "Selecionar a si mesmo limpa o alvo, para a câmera ficar sobre o seu ombro. Curas e bônus ainda caem em você."
L["Shows our own copy of your target frame, so it matches only the game's look or a Cinematic theme."] = "Mostra a nossa própria cópia do seu quadro de alvo, para ele combinar só com a aparência do jogo ou com um tema do Cinematic."
L["How long the Shoulder Cam waits to come back over your shoulder after you step outside or get off your mount. Going back in or mounting again during the wait starts it over."] = "Quanto tempo a Câmera de ombro espera para voltar sobre o seu ombro depois que você sai de um lugar fechado ou desmonta. Voltar para dentro ou montar de novo durante a espera recomeça a contagem."
L["Turns to who you talk to everywhere, so the other columns don't matter."] = "Vira para quem você conversa em todo lugar, então as outras colunas não importam."
L["How many seconds the camera takes to move behind you for this camera. Leave it empty to use %s."] = "Quantos segundos a câmera leva para ir para trás de você nesta câmera. Deixe vazio para usar %s."

-- Camera/SkyrideCam.lua
L["Everywhere you skyride, so the other columns don't matter."] = "Em todo lugar onde você faz voo dinâmico, então as outras colunas não importam."
L["How far past your cruise distance (set in Take off) the camera goes."] = "O quanto a câmera vai além da sua distância de cruzeiro (definida em Decolar)."
L["At 0.5 it's a snap, as fast as the game's zoom can go."] = "Em 0.5 é instantâneo, tão rápido quanto o zoom do jogo consegue."
L["How close the camera comes in. Set to 0 to keep its distance."] = "O quanto a câmera se aproxima. Ponha em 0 para manter a distância."
L["Second Wind brings the camera in a little, then back out."] = "Fôlego Renovado aproxima um pouco a câmera, depois a afasta de novo."
L["The fastest the camera can move. Moves that would go faster take longer instead."] = "A velocidade máxima da câmera. Movimentos que seriam mais rápidos levam mais tempo."
L["Blends one move into the next. At 0 the camera stops between moves."] = "Emenda um movimento no outro. Em 0 a câmera para entre os movimentos."

-- Camera/TriggersPage.lua
L["For now, its camera follows its own rules for when it plays."] = "Por enquanto, a câmera dela segue as próprias regras de quando tocar."
L["Moves it up, so it wins over the one above."] = "Sobe, para vencer o de cima."
L["Moves it down, so the one below wins over it."] = "Desce, para o de baixo vencer."
L["Makes a copy of this trigger that you can change on its own."] = "Faz uma cópia deste gatilho que você pode mudar à parte."
L["Puts its Only if, wait, cooldown, chance and priority back to how they came."] = "Volta o Só se, a espera, a recarga, a chance e a prioridade a como vieram."
L["A wait before it starts, a minimum time, a cooldown and a chance."] = "Uma espera antes de começar, um tempo mínimo, uma recarga e uma chance."
L["A rule that must be true for it to start. Leave it empty to always start. Click to edit."] = "Uma regra que tem que ser verdadeira para começar. Deixe vazio para sempre começar. Clique para editar."
L["When on, it waits until its condition is no longer true before it can start again."] = "Ativado, espera a condição deixar de ser verdadeira antes de poder começar de novo."

