L["How solid speech from behind you looks. Fainter makes it seem muffled and out of view."] = "O quanto a fala vinda de trás de você parece sólida. Mais fraca parece abafada e fora de vista."

-- Style/CdmStyle.lua
L["After a few hits"] = "Depois de alguns golpes"
L["Draining"] = "Esvaziando"
L["Just cast"] = "Acabou de lançar"
L["Halfway"] = "Na metade"
L["Cooldown Manager Style"] = "Estilo do Gerenciador de recargas"
L["How the drain ring on your tracked buffs looks. Pick which buffs get one on the Cooldown Manager page, under Look."] = "A aparência do anel que esvazia nos seus bônus rastreados. Escolha quais bônus ganham um na página Gerenciador de recargas, em Aparência."
L["Turns this page's ring look on or off. Off: the ring's own look."] = "Ativa ou desativa a aparência do anel desta página. Desativado: a aparência própria do anel."
L["How the drain ring on your tracked buffs looks."] = "A aparência do anel que esvazia nos seus bônus rastreados."
L["The Cooldown Manager icons' shape."] = "O formato dos ícones do Gerenciador de recargas."
L["Cooldown + DoT"] = "Recarga + dano periódico"
L["How a spell's cooldown shows over its DoT, on rows whose Shows is Both."] = "Como a recarga de um feitiço aparece sobre o dano periódico dele, nas linhas em que Mostra é Ambos."
L["The icons take Action Bar Style's shape."] = "Os ícones pegam o formato do Estilo das barras de ações."
L["Square icons, whatever the action buttons are."] = "Ícones quadrados, sejam como forem os botões de ação."
L["Round icons, whatever the action buttons are."] = "Ícones redondos, sejam como forem os botões de ação."
L["Pips"] = "Pontos"
L["Eight chunky segments round the icon."] = "Oito segmentos grossos em volta do ícone."
L["One thin ring round the icon."] = "Um anel fino em volta do ícone."
L["Liquid"] = "Líquido"
L["The icon empties from the top down."] = "O ícone esvazia de cima para baixo."
L["Bar under"] = "Barra embaixo"
L["A thin bar under the icon."] = "Uma barra fina embaixo do ícone."
L["How big the ring is next to the icon."] = "O tamanho do anel em relação ao ícone."
L["Empty part"] = "Parte vazia"
L["How dark the spent part shows. 0: hidden."] = "O quanto a parte gasta aparece escura. 0: oculta."
L["The ring in your class's color."] = "O anel na cor da sua classe."
L["From the full end's color to the empty end's: what's left turns toward the empty color as it drains."] = "Da cor da ponta cheia para a da ponta vazia: o que sobra vai ganhando a cor vazia conforme esvazia."
L["The color you pick below."] = "A cor que você escolhe abaixo."
L["A plain white ring."] = "Um anel branco simples."
L["Click to choose the ring's color."] = "Clique para escolher a cor do anel."
L["Full end"] = "Ponta cheia"
L["The gradient's color where the shield is full."] = "A cor do degradê onde o escudo está cheio."
L["Empty end"] = "Ponta vazia"
L["The gradient's color where the shield runs out."] = "A cor do degradê onde o escudo acaba."
L["Left / right"] = "Esquerda / direita"
L["Moves the amount left or right from the icon's middle."] = "Move o valor para a esquerda ou a direita do meio do ícone."
L["Down / up"] = "Baixo / cima"
L["Moves the amount down or up from the icon's middle."] = "Move o valor para baixo ou para cima do meio do ícone."
L["How big the amount's text is."] = "O tamanho do texto do valor."
L["Which buffs get a ring, and the game's timer: the Cooldown Manager page, under Look."] = "Quais bônus ganham um anel, e o cronômetro do jogo: a página Gerenciador de recargas, em Aparência."
L["Pips in a ring round the icon."] = "Pontos num anel em volta do ícone."
L["Edge pips"] = "Pontos na borda"
L["Square pips along the icon's edge."] = "Pontos quadrados ao longo da borda do ícone."
L["Row pips"] = "Pontos em fila"
