-- Style/CombatTextPage.lua
L["You may see other people's damage as your own."] = "Você pode ver o dano de outras pessoas como se fosse seu."
L["Each text starts out looking like the one it's under. Changing one only changes that one."] = "Cada texto começa com a aparência do que está acima dele. Mudar um só muda aquele."
L["Spells"] = "Feitiços"
L["A look of their own for any of your spells."] = "Uma aparência própria para qualquer feitiço seu."
L["Ours look the way the Look tab sets them. The game's look as they always do."] = "Os nossos seguem a aba Aparência. Os do jogo ficam como sempre."
L["The game's own numbers, the way it normally draws them."] = "Os números do próprio jogo, do jeito que ele normalmente os desenha."
L["Set XP and other floating text to The game's first. While it's on None, the game draws none of its numbers."] = "Ponha XP e outros textos flutuantes em Do jogo primeiro. Enquanto estiver em Nenhuma, o jogo não desenha nenhum número."
L["Ours when you're solo. In a group or raid, the game's own, which show every pet hit."] = "Os nossos quando você está sozinho. Em grupo ou raide, os do jogo, que mostram cada golpe do ajudante."
L["In a group, ours only show your pet's spells, since its swings look the same as everyone else's. The game's shows every pet hit in its own look."] = "Em grupo, os nossos só mostram os feitiços do seu ajudante, já que os golpes dele parecem iguais aos de todo mundo. O do jogo mostra cada golpe do ajudante com a aparência dele."
L["Hides all the game's floating text, damage numbers included. Log out and back in to apply."] = "Oculta todo o texto flutuante do jogo, números de dano incluídos. Saia e entre de novo para aplicar."
L["Log out and back in to apply. With it hidden the game draws none of its numbers, so The game's is grayed out in the rows above."] = "Saia e entre de novo para aplicar. Com ele oculto, o jogo não desenha nenhum número, então Do jogo fica cinza nas linhas acima."
L["Log out and back in to apply: until then the game's floating text stays hidden."] = "Saia e entre de novo para aplicar: até lá, o texto flutuante do jogo fica oculto."
L["None hides all of the game's floating text, damage numbers included. It takes a log out and back in."] = "Nenhuma oculta todo o texto flutuante do jogo, números de dano incluídos. Precisa sair e entrar de novo."
L["Each row sets many texts at once. You can change any of them afterward in the table below."] = "Cada linha ajusta vários textos de uma vez. Você pode mudar qualquer um depois na tabela abaixo."
L["Shows only your crits and misses, with plain hits and heals turned off."] = "Mostra só os seus críticos e erros, com os golpes e curas normais desligados."
L["Plain hits and heals are off and crits and misses are on. Switch any of them back in the table."] = "Golpes e curas normais estão desligados e críticos e erros estão ligados. Troque qualquer um de volta na tabela."
L["Turns off your auto attacks, along with their crits and misses."] = "Desliga os seus ataques automáticos, junto com os críticos e erros deles."
L["Crits and your casts show in the middle, and the rest move aside."] = "Críticos e os seus lançamentos aparecem no meio, e o resto vai para o lado."
L["Your pet's hits show smaller than yours."] = "Os golpes do seu ajudante aparecem menores que os seus."
L["Your pet's hits show as big as yours."] = "Os golpes do seu ajudante aparecem do tamanho dos seus."
L["Every number is three quarters of the game's size."] = "Todo número tem três quartos do tamanho do jogo."
L["Swings are smaller, and spells and heals get bigger the longer their cast."] = "Golpes ficam menores, e feitiços e curas ficam maiores quanto mais longo o lançamento."
L["Every number stays three quarters as long as the game's."] = "Todo número fica três quartos do tempo do jogo."
L["Swings stay up for less time, and spells and heals stay longer the longer their cast."] = "Golpes ficam menos tempo, e feitiços e curas ficam mais tempo quanto mais longo o lançamento."
L["Puts everything on this tab back to its defaults."] = "Volta tudo nesta aba ao padrão."
L["How big it is compared to the game's."] = "O tamanho em relação ao do jogo."
L["How big its crits are compared to its hits."] = "O tamanho dos críticos em relação aos golpes."
L["Adds (Glancing), (Blocked) or (Resisted) after the number. In a fight, the amount is hidden."] = "Adiciona (Golpe de raspão), (Bloqueado) ou (Resistido) depois do número. Em combate, o valor fica oculto."
L["How far it moves compared to the game's."] = "O quanto ele se move em relação ao do jogo."
L["How long it stays compared to the game's."] = "Quanto tempo ele fica em relação ao do jogo."
L["How far into its time on screen it starts to fade."] = "Em que ponto do tempo na tela ele começa a esmaecer."
L["Grows big for a moment, then settles, like the game's crits."] = "Cresce por um instante, depois volta, como os críticos do jogo."
L["Shows or hides it. Turning it off hides the texts under it too, except crits, which have their own."] = "Mostra ou oculta. Desligar oculta também os textos abaixo dele, menos os críticos, que têm o seu próprio."
