-- Style/LetterboxStyle.lua
L["Preview:"] = "Pré-visualização:"
L["The weather the Preview shows."] = "O clima que a Pré-visualização mostra."
L["Shows this weather's tint at its heaviest for a few seconds (at 50% while Strength is Off)."] = "Mostra a tonalidade deste clima no máximo por alguns segundos (a 50% enquanto Intensidade estiver em Desativado)."
L["On the screen"] = "Na tela"
L["Shows it for a few seconds, in CineMode or not (at 50% while it's Off)."] = "Mostra por alguns segundos, no CineMode ou não (a 50% enquanto estiver em Desativado)."
L["Heavier weather"] = "Clima mais forte"
L["Medium"] = "Médio"
L["Heavy"] = "Forte"
L["Makes the game's own rain and snow thicker while its row is on, and puts yours back after."] = "Deixa a chuva e a neve do próprio jogo mais densas enquanto a linha está ativa, e volta as suas depois."
L["Pulls the view distance in as a downpour would, for a few seconds."] = "Diminui a distância de visão como um temporal faria, por alguns segundos."
L["The world"] = "O mundo"
L["Draw the world between the bars"] = "Desenhar o mundo entre as faixas"
L["Shows the whole view between the bars instead of hiding its top and bottom (it changes only out of fights)."] = "Mostra a vista inteira entre as faixas em vez de esconder o topo e a base (só muda fora de combate)."
L["Shows the whole time in CineMode, including fights and the Calm Timer after them."] = "Aparece o tempo todo no CineMode, incluindo lutas e o Cronômetro de calma depois delas."
L["When on, the bars look the way this page sets them. When off, they're Cinematic's plain black bars."] = "Ativado, as faixas ficam do jeito que esta página manda. Desativado, são as faixas pretas simples do Cinematic."
L["Takes the bars out and brings them back in, like at the start and end of a fight."] = "Tira as faixas e as traz de volta, como no começo e no fim de uma luta."
L["Shapes the space between the bars like a movie screen, on any monitor."] = "Dá ao espaço entre as faixas o formato de uma tela de cinema, em qualquer monitor."
L["How tall the top bar is, as a share of the screen's height."] = "A altura da faixa de cima, como parte da altura da tela."
L["Click to link or unlink the two bars. Linked, they're the same height."] = "Clique para ligar ou desligar as duas faixas. Ligadas, têm a mesma altura."
L["How tall the bottom bar is, as a share of the screen's height."] = "A altura da faixa de baixo, como parte da altura da tela."
L["How long the bars take to come in or go. Set to 0 to match the UI's fade."] = "Quanto tempo as faixas levam para entrar ou sair. Ponha em 0 para acompanhar o esmaecimento da interface."
L["How the weather tints the scene: a color for each weather, and how fast it comes in and goes."] = "Como o clima tinge a cena: uma cor para cada clima, e o quão rápido ele chega e vai embora."
L["When on, the weather uses the colors and time set here. When off, Cinematic's own."] = "Ativado, o clima usa as cores e o tempo definidos aqui. Desativado, os do próprio Cinematic."
L["Pick this weather's tint. White is no change; darker colors darken the scene more."] = "Escolha a tonalidade deste clima. Branco não muda nada; cores mais escuras escurecem mais a cena."
L["How long the weather's tint takes to come in as it starts, or to go as it clears or you step inside."] = "Quanto tempo a tonalidade do clima leva para chegar quando ele começa, ou para sumir quando o tempo abre ou você entra num lugar fechado."

-- Style/MinimapStyle.lua
L["Minimap Style"] = "Estilo do minimapa"
L["How the minimap looks: its shape, border and ring."] = "A aparência do minimapa: o formato, a borda e o anel."
L["Turns this page's minimap look on or off."] = "Ativa ou desativa a aparência do minimapa desta página."
L["Size and shape"] = "Tamanho e formato"
L["How big the minimap is."] = "O tamanho do minimapa."
L["Makes the minimap square."] = "Deixa o minimapa quadrado."
L["Border size"] = "Tamanho da borda"
L["How thick the border round the square minimap is. 0: no border."] = "A espessura da borda em volta do minimapa quadrado. 0: sem borda."
L["Border color:"] = "Cor da borda:"
L["Theme uses your theme's ring color, or black when it has none."] = "Tema usa a cor do anel do seu tema, ou preto quando ele não tem."
L["Zone name and clock inside"] = "Nome da zona e relógio dentro"
L["Puts the zone name at the top of the square minimap and the clock in its corner."] = "Põe o nome da zona no topo do minimapa quadrado e o relógio no canto."
L["Zoom buttons"] = "Botões de zoom"
L["Hides the minimap's zoom buttons."] = "Oculta os botões de zoom do minimapa."
L["Hides the zone name bar over the minimap."] = "Oculta a barra com o nome da zona sobre o minimapa."
L["Hides the day and night dial on the minimap's edge."] = "Oculta o relógio de dia e noite na borda do minimapa."
L["Ring and buttons"] = "Anel e botões"
L["Colors the rings around minimap buttons in your theme's ring color, or the border color when it has none."] = "Pinta os anéis em volta dos botões do minimapa com a cor do anel do seu tema, ou com a cor da borda quando ele não tem."
L["A little shading just inside the ring, so the map looks set into it."] = "Uma leve sombra logo dentro do anel, para o mapa parecer encaixado nele."
L["Zone bar in the theme's look"] = "Barra da zona com a aparência do tema"
L["Shade and the zone bar's look come with themes that have a ring color."] = "A sombra e a aparência da barra da zona vêm com temas que têm cor de anel."

-- Style/PersonalStyle.lua
L["When on, the bars look the way this page sets them. When off, they use the game's own look."] = "Ativado, as barras ficam do jeito que esta página manda. Desativado, usam a aparência do próprio jogo."
L["It fades to a darker shade of its own color."] = "Vai escurecendo para um tom mais escuro da própria cor."
L["Its width in screen pixels, so the same number gives two bars the same width."] = "A largura em pixels da tela, para o mesmo número dar a duas barras a mesma largura."
L["The health bar's width, growing out from its middle."] = "A largura da barra de vida, crescendo a partir do meio."
L["The power bar's width, growing out from its middle."] = "A largura da barra de poder, crescendo a partir do meio."
L["The mana bar's width as a percent of the game's power bar, growing out from its middle."] = "A largura da barra de mana como porcentagem da barra de poder do jogo, crescendo a partir do meio."
L["The health bar's height compared to the game's."] = "A altura da barra de vida em relação à do jogo."
L["The power bar's height compared to the game's."] = "A altura da barra de poder em relação à do jogo."
L["How big your class resource is compared to the game's size."] = "O tamanho do seu recurso de classe em relação ao tamanho do jogo."
L["The mana bar's height compared to the power bar's."] = "A altura da barra de mana em relação à da barra de poder."
L["The bars' border: the game's or one of ours. Custom sets its thickness and color below."] = "A borda das barras: a do jogo ou uma das nossas. Personalizada define a espessura e a cor abaixo."

-- Style/PlateCastStyle.lua
L["When on, the cast bars look the way this page sets them. When off, they use the game's own look."] = "Ativado, as barras de lançamento ficam do jeito que esta página manda. Desativado, usam a aparência do próprio jogo."
L["Makes it part of the unit frame, with its fill, border and font, right under its bars."] = "Faz dela parte do quadro de unidade, com o preenchimento, a borda e a fonte dele, logo embaixo das barras."
L["Pick the color of an interrupted cast. The game doesn't report this in every fight."] = "Escolha a cor de um lançamento interrompido. O jogo não avisa isso em toda luta."
L["How dark it is behind the fill. This only works with a fill of your own; the game's keeps its own."] = "O quanto fica escuro atrás do preenchimento. Só funciona com um preenchimento seu; o do jogo mantém o próprio."
L["Its width compared to the game's, growing out from its middle. Nameplates only."] = "A largura em relação à do jogo, crescendo a partir do meio. Só placas de identificação."
L["The cast bar's height compared to the game's."] = "A altura da barra de lançamento em relação à do jogo."
L["The icon's size compared to the game's."] = "O tamanho do ícone em relação ao do jogo."
L["A dark shadow behind the letters, down and to the right."] = "Uma sombra escura atrás das letras, para baixo e para a direita."
L["The look every cast bar uses while its row is set to Default."] = "A aparência que toda barra de lançamento usa enquanto a linha dela está em Padrão."
L["Default's (Cast Bars)"] = "O do Padrão (Barras de lançamento)"

-- Style/QuestItemStyle.lua
L["When on, the button looks the way this page sets it. When off, it looks like the game's extra ability button."] = "Ativado, o botão fica do jeito que esta página manda. Desativado, parece o botão de habilidade extra do jogo."
L["Icons have their own dark border. Zooming in a little cuts it off."] = "Os ícones têm a própria borda escura. Ampliar um pouco a corta."
L["A black border around its numbers."] = "Uma borda preta em volta dos números."

-- Style/QuestTalkStyle.lua
L["When on, the dialogue looks the way this page sets it. When off, it uses the game's parchment."] = "Ativado, o diálogo fica do jeito que esta página manda. Desativado, usa o pergaminho do jogo."
L["The size of the bubble and the reply list. Their text grows with them."] = "O tamanho do balão e da lista de respostas. O texto cresce junto."
L["A black border around the letters, for light text with no panel behind it."] = "Uma borda preta em volta das letras, para texto claro sem painel atrás."
L["The bubble's text in a color of your own. The quest card keeps its own color."] = "O texto do balão numa cor sua. O cartão da missão mantém a própria cor."

-- Style/RaidStyle.lua
L["When on, the raid frames look the way this page sets them. When off, they use the game's own look."] = "Ativado, os quadros de raide ficam do jeito que esta página manda. Desativado, usam a aparência do próprio jogo."
L["Uses the color below at full health, shifting to the At half and Empty colors as health drops."] = "Usa a cor abaixo com a vida cheia, passando para as cores Na metade e Vazia conforme a vida cai."
L["Tints the game's background a color of your own, picked below."] = "Pinta o fundo do jogo com uma cor sua, escolhida abaixo."
L["The name's size compared to the game's."] = "O tamanho do nome em relação ao do jogo."
L["The look every group uses while its row is set to Same as the Default row."] = "A aparência que todo grupo usa enquanto a linha dele está em Igual à linha Padrão."

-- Style/RollStyle.lua
L["When on, the window looks the way this page sets it. When off, it uses Roll Vision's usual look."] = "Ativado, a janela fica do jeito que esta página manda. Desativado, usa a aparência de sempre do Roll Vision."
L["A dark panel with a thin line around it, in the item's quality color."] = "Um painel escuro com uma linha fina em volta, na cor da qualidade do item."

