L["Its cards on or off, and where each shows."] = "Os cartões ativos ou não, e onde cada um aparece."
L["Resets this card's own settings so they come from its card type again."] = "Redefine as configurações próprias deste cartão para voltarem a vir do tipo de cartão."
L["Puts all your changes to this card type back to the defaults."] = "Volta todas as suas mudanças neste tipo de cartão ao padrão."
L["No new Zone or Subzone card for this long after one. Set to 0 to show one every time."] = "Nenhum cartão novo de Zona ou Subzona por esse tempo depois de um. Ponha em 0 para mostrar sempre."
L["The words as you go into a fight against players; leave empty for none."] = "As palavras quando você entra numa luta contra jogadores; deixe vazio para nenhuma."
