L["The opening words (on a card, over the zone name)."] = "As palavras de abertura (num cartão, sobre o nome da zona)."
L["Its usual card, in its own look (the Style tab)."] = "O cartão de sempre, com a aparência própria (a aba Estilo)."
L["A picture in its own colors: red with a dark outline on a flat black band."] = "Uma imagem nas próprias cores: vermelho com contorno escuro numa faixa preta lisa."
L["Shows the line only this long at the start and end. All the way left (Off) shows it the whole way."] = "Mostra a linha só esse tempo no começo e no fim. Tudo para a esquerda (Desativado) mostra o tempo todo."

