-- Visions/DamageVision.lua
L["Shows in every fight, wherever you are, so the other columns don't matter."] = "Aparece em toda luta, onde quer que você esteja, então as outras colunas não importam."
L["Shows how you did on that boss as it dies."] = "Mostra como você foi naquele chefe quando ele morre."
L["Shows how you did on the whole run once it's done."] = "Mostra como você foi na incursão toda quando ela acaba."
L["Shows the recap card with the meter's whole run if you have one, or a made-up one if not (Stop hides it)."] = "Mostra o cartão de resumo com a incursão toda do medidor, se você tiver uma, ou um inventado, se não (Parar o oculta)."
L["Shows your place over it (#2)."] = "Mostra a sua posição acima dele (#2)."
L["A crown pops in as you take #1."] = "Uma coroa aparece quando você assume o #1."
L["Shows the name of the one you race, in their class's color."] = "Mostra o nome de quem você está disputando, na cor da classe dele."
L["Shows your damage (or healing) so far."] = "Mostra o seu dano (ou cura) até agora."
L["Shows each player's name on their row."] = "Mostra o nome de cada jogador na linha dele."
L["Amber while you're behind, teal once you lead, or two colors of your own."] = "Âmbar enquanto você está atrás, verde-azulado quando passa à frente, ou duas cores suas."

-- Visions/EmoteVision.lua
L["Emote Vision test: you'd %s."] = "Teste do Emote Vision: você faria %s."
L["Turn it on and pick which moments show a card, and the emotes on each."] = "Ative e escolha quais momentos mostram um cartão, e as expressões de cada um."
L["Cards that need the other player's nameplate. CineMode keeps it for them."] = "Cartões que precisam da placa do outro jogador. O CineMode a mantém para eles."
L["Puts the menu's emotes back to the defaults."] = "Volta as expressões do menu ao padrão."
L["Shows wherever you are, but never in a fight. A card that comes up in a fight waits for it to end."] = "Aparece onde quer que você esteja, mas nunca em combate. Um cartão que surge em combate espera a luta acabar."
L["Puts every moment's emotes back to the defaults."] = "Volta as expressões de todos os momentos ao padrão."
L["Only buffs from strangers bring up a card, not buffs from your party or raid."] = "Só bônus de desconhecidos trazem um cartão, não bônus do seu grupo ou raide."

-- Page names and lists
L["A Minimap page in the Style hub: make the minimap square with a border in your theme's color, change its size, and hide its zoom buttons, zone bar or day and night dial."] = "Uma página Minimapa no Estilo: deixe o minimapa quadrado com uma borda na cor do seu tema, mude o tamanho e oculte os botões de zoom, a barra da zona ou o relógio de dia e noite."
L["A boss down in a dungeon or raid with your group (each one, not just the last): the emotes go to everyone."] = "Um chefe derrotado numa masmorra ou raide com o seu grupo (cada um, não só o último): as expressões vão para todo mundo."
L["A boss's name as a title card, as its fight starts or as you first target it or come near: on the screen, in a letterbox bar or low on the left like a film, with its dungeon and which boss it is. Its look has its own tab on Battle Vision's Style page."] = "O nome de um chefe como cartão de título, quando a luta começa ou quando você o mira ou chega perto pela primeira vez: na tela, numa faixa ou embaixo à esquerda como num filme, com a masmorra e qual chefe é. A aparência tem uma aba própria na página Estilo do Battle Vision."
L["A buff of a minute or more someone else puts on you (Fortitude, Arcane Intellect, a blessing...). Not heals over time."] = "Um bônus de um minuto ou mais que outra pessoa põe em você (Fortitude, Intelecto Arcano, uma bênção...). Não curas ao longo do tempo."
L["A button on the inspect window opens the player's talents, and one on the talents window takes you back."] = "Um botão na janela de inspecionar abre os talentos do jogador, e um na janela de talentos leva você de volta."
L["A calculator button on your talents window opens a talent planner that looks just like it, starting from your talents. Plan a build, see the level it needs, then copy it over to your talents window to apply."] = "Um botão de calculadora na sua janela de talentos abre um planejador de talentos igualzinho a ela, começando pelos seus talentos. Monte uma build, veja o nível que ela precisa, depois copie para a sua janela de talentos para aplicar."
L["A cue as you go into a fight and come out of it: a word on the screen or in a letterbox bar, a pulse around the edges, an icon, and sounds you pick for each kind of fight, like horns for a raid boss. Its look has a page in the Style hub, with presets and a preview."] = "Um aviso quando você entra numa luta e quando sai: uma palavra na tela ou numa faixa, um pulso em volta das bordas, um ícone e sons que você escolhe para cada tipo de luta, como trombetas para um chefe de raide. A aparência tem uma página no Estilo, com predefinições e pré-visualização."
L["A grid that shows or hides each part of the nameplates in CineMode: health bar, name, cast bar, buffs, level and more."] = "Uma grade que mostra ou oculta cada parte das placas no CineMode: barra de vida, nome, barra de lançamento, bônus, nível e mais."
L["A mark on your target's nameplate for when no target frame shows who you've got: an arrow, chevron, glow or brackets, colored by how they see you."] = "Uma marca na placa do seu alvo para quando nenhum quadro de alvo mostra quem você pegou: uma seta, um V, um brilho ou colchetes, na cor de como ele vê você."
L["A new Retail profile gives WoW Forever retail's look: Cinematic's own Edit Mode layout, with action bars 1 to 3, the micro menu and bags, and the XP bar each coming up on its own. Switch back to Default and your own layout returns."] = "Um novo Perfil de retail dá ao WoW Forever a aparência do retail: o layout do Modo de Edição do próprio Cinematic, com as barras de ações 1 a 3, o micromenu e as bolsas, e a barra de XP, cada um aparecendo por conta própria. Volte para Padrão e o seu layout volta."
L["A new Spells tab on Combat Text Style gives any of your spells its own color, size and look, its crits and DoT ticks too."] = "Uma nova aba Feitiços no Estilo do texto de combate dá a qualquer feitiço seu uma cor, um tamanho e uma aparência próprios, com os críticos e os pulsos de dano periódico também."
L["A new Vision for the words that fade in on your screen between fights: what you did last time as you log in (\"Last time: Darkshore · 3 quests done · reached level 24\"), the time of day, a place under attack, and the death banner, each with its own tick and a Test button. Combat Vision is now called Battle Vision."] = "Uma nova Vision para as palavras que surgem na sua tela entre as lutas: o que você fez da última vez, ao entrar no jogo (\"Da última vez: Costa Negra · 3 missões concluídas · chegou ao nível 24\"), a hora do dia, um lugar sob ataque e a faixa de morte, cada um com a sua marcação e um botão Testar. O Combat Vision agora se chama Battle Vision."
L["A new Wheels page shows every wheel and its icons, with its keybind right there, and lets you pick which wheels sit on the master wheel and in what order."] = "Uma nova página Rodas mostra cada roda e os ícones dela, com o atalho ali mesmo, e deixa você escolher quais rodas ficam na roda principal e em que ordem."
L["A new page in the Community hub with links to the Discord, YouTube, CurseForge and GitHub, ready to copy."] = "Uma nova página em Comunidade com links para o Discord, YouTube, CurseForge e GitHub, prontos para copiar."
L["A new rule editor"] = "Um novo editor de regras"
L["A place new to you: a zone the first time you're there, a subzone as the game says you discovered it, a dungeon or raid the first time you go in. In place of the Zone or Subzone card."] = "Um lugar novo para você: uma zona na primeira vez que você vai lá, uma subzona quando o jogo diz que você a descobriu, uma masmorra ou raide na primeira vez que você entra. No lugar do cartão de Zona ou Subzona."
L["A track with you above it and your rival below; the gap between you in color."] = "Uma pista com você em cima e o seu rival embaixo; a diferença entre vocês em cor."
L["After an update with new features, a line in chat at login says so, with a link to What's new. Turn it off on the Chat page."] = "Depois de uma atualização com recursos novos, uma linha no bate-papo ao entrar avisa, com um link para Novidades. Desative na página Bate-papo."
L["An over-the-shoulder camera: you sit to one side of the screen and stay there as you zoom. Swap shoulders with a key, turn toward the NPCs you talk to and the enemies you target, and let your cast bar and resources slide along with you."] = "Uma câmera sobre o ombro: você fica de um lado da tela e continua lá ao dar zoom. Troque de ombro com uma tecla, vire para os PNJs com quem fala e os inimigos que mira, e deixe a sua barra de lançamento e os recursos deslizarem junto com você."
L["Arcane stars"] = "Estrelas arcanas"
L["As a dungeon's or raid's last boss goes down: its name, the time since you came in and how many times you died."] = "Quando o último chefe de uma masmorra ou raide cai: o nome dela, o tempo desde que você entrou e quantas vezes você morreu."
L["As you cast your Hearthstone, Astral Recall or a teleport, a portal opens around you in your class and spec's color, closing in as the cast fills, then the screen goes black as you're whisked away. It plays alongside the tele camera."] = "Quando você usa a Pedra de Regresso, a Evocação Astral ou um teleporte, um portal se abre em volta de você na cor da sua classe e especialização, se fechando conforme o lançamento avança, depois a tela fica preta enquanto você é levado embora. Toca junto com a câmera de teleporte."
L["As you come into an inn or a city (not at login, not in a fight): the place's name. The same place at most once every 10 minutes."] = "Quando você chega numa estalagem ou cidade (não ao entrar no jogo, não em combate): o nome do lugar. O mesmo lugar no máximo uma vez a cada 10 minutos."
L["As you reach a new level (after the fight, if you're in one): the level, the zone and how long it took this session. Max level at the cap."] = "Quando você sobe de nível (depois da luta, se estiver em uma): o nível, a zona e quanto tempo levou nesta sessão. Nível máximo no limite."
L["As you turn in a story quest (campaign, important or legendary) or a dungeon, raid or elite one: its title."] = "Quando você entrega uma missão de história (campanha, importante ou lendária) ou uma de masmorra, raide ou elite: o título dela."
L["As your health drops, dark edges creep in around the screen with art themed to your class and talents (blood, frost, fire...), a heartbeat that quickens and a flash on big hits, so you can tell how you're doing at a glance."] = "Conforme a sua vida cai, bordas escuras avançam em volta da tela com arte no tema da sua classe e talentos (sangue, gelo, fogo...), batimentos que aceleram e um lampejo em golpes fortes, para você saber como está só de olhar."
L["At an NPC"] = "Num PNJ"
L["BigWigs, TomTom, HealBot Continued and Titan Panel get rows of their own and fade with Cinematic. Platynator and Threat Plates nameplates fade in CineMode, and Prat 3.0's chat follows the Chat page."] = "BigWigs, TomTom, HealBot Continued e Titan Panel ganham linhas próprias e esmaecem com o Cinematic. As placas do Platynator e do Threat Plates esmaecem no CineMode, e o bate-papo do Prat 3.0 segue a página Bate-papo."
L["Blood mist"] = "Névoa de sangue"
L["Camera Modes and Camera Triggers are now one Cameras page: a row for each trigger (an emote, a campfire, going AFK, a flight...) with the camera it starts, its music and CineMode, and where it can start. Copy a row to give a trigger a different camera in other places."] = "Modos de câmera e Gatilhos de câmera agora são uma página só, Câmeras: uma linha para cada gatilho (uma expressão, uma fogueira, ficar LDT, um voo...) com a câmera que ele inicia, a música e o CineMode, e onde pode começar. Copie uma linha para dar a um gatilho uma câmera diferente em outros lugares."
L["Change any Vitals Vision theme's art, colors, sparks and heartbeat, or make themes of your own from one, and rename or delete them. Reset theme puts one of ours back as it comes."] = "Mude a arte, as cores, as faíscas e os batimentos de qualquer tema do Vitals Vision, ou crie temas seus a partir de um, e renomeie ou exclua. Redefinir tema volta um dos nossos a como vem."
L["ClassicUI Forever's action bars, bar art and quest watch now fade with Cinematic, and come back when you hover them."] = "As barras de ações, a arte das barras e o acompanhamento de missões do ClassicUI Forever agora esmaecem com o Cinematic, e voltam quando você passa o mouse."
L["Click the star beside any settings page's search box to save that page, open at the tab you're on. Your favorites get their own line at the top of Cinematic's list."] = "Clique na estrela ao lado da caixa de busca de qualquer página de configurações para salvar a página, aberta na aba em que você está. Os seus favoritos ganham uma linha própria no topo da lista do Cinematic."
L["Combat text by spell"] = "Texto de combate por feitiço"
L["Cooldown Manager grid"] = "Grade do Gerenciador de recargas"
L["Creeping shadow"] = "Sombra rastejante"
L["Ctrl+Click an auction to see it on your character in a small dressing room beside the Auction House, which now stays open. Turn it on in Quality of Life."] = "Ctrl+Clique num leilão para ver o item no seu personagem num pequeno provador ao lado da Casa de Leilões, que agora fica aberta. Ative em Conveniência."
L["Dressing room at the Auction House"] = "Provador na Casa de Leilões"
L["Earth wisps"] = "Lumes de terra"
L["ElvUI's frames, Deadly Boss Mods' timer bars and RestedXP's guide window now fade in CineMode: ElvUI's following the Game Frames rows of the frames they replace, RestedXP's with the Quest tracker row."] = "Os quadros do ElvUI, as barras de tempo do Deadly Boss Mods e a janela de guia do RestedXP agora esmaecem no CineMode: os do ElvUI seguindo as linhas de Quadros padrão dos quadros que substituem, a do RestedXP com a linha Rastreador de missões."
L["Embers"] = "Brasas"
L["Every camera is now a script of steps (turn, zoom, sway, wait, follow...) on the new Scripts page in the Camera hub. Pick one to see how it moves, change its steps and settings there, or copy it to make a camera of your own."] = "Toda câmera agora é um roteiro de passos (girar, zoom, balançar, esperar, seguir...) na nova página Roteiros, em Câmera. Escolha uma para ver como ela se move, mude os passos e as configurações ali, ou copie para fazer uma câmera sua."
L["Every grid now has the same row: Always, then Combat, Target and Location dropdowns, Roles and Edit. Edit turns a row into a rule, for AND, NOT, Cities and more, with a dot showing whether it's on right now. Chat bubbles, tooltips, effects, music and the cameras now say where they show instead of where they hide."] = "Toda grade agora tem a mesma linha: Sempre, depois as listas Combate, Alvo e Localização, Funções e Editar. Editar transforma uma linha numa regra, para AND, NOT, Cidades e mais, com um ponto mostrando se está ativa agora. Balões de fala, dicas, efeitos, música e as câmeras agora dizem onde aparecem em vez de onde se ocultam."
L["Fel wisps"] = "Lumes vis"
L["FlareUI's unit frames, resource bars, buffs, quest tracker, party and raid frames fade in CineMode, following the Game Frames rows of the frames they replace."] = "Os quadros de unidade, as barras de recurso, os bônus, o rastreador de missões e os quadros de grupo e raide do FlareUI esmaecem no CineMode, seguindo as linhas de Quadros padrão dos quadros que substituem."
L["Frames Forever's unit frames follow the Game Frames rows of the frames they replace. ShamanPower's totem bar fades with the Totem bar row, and its cooldown bar gets a row of its own."] = "Os quadros de unidade do Frames Forever seguem as linhas de Quadros padrão dos quadros que substituem. A barra de totens do ShamanPower esmaece com a linha Barra de totens, e a barra de recargas dele ganha uma linha própria."
L["Frost creeps in on the screen's edges in snow, rain runs down the lens, and lightning flashes with thunder in storms. Off to start with: turn each up on the Weather page."] = "A geada avança pelas bordas da tela na neve, a chuva escorre pela lente e os relâmpagos piscam com trovões nas tempestades. Desligado no começo: aumente cada um na página Clima."
L["Gliding"] = "Planando"
L["Green wisps"] = "Lumes verdes"
L["Guidelime support"] = "Suporte ao Guidelime"
L["Guidelime's guide window, its ongoing steps and its waypoint arrow get a row each, so you can hide the guide and keep the arrow pointing the way."] = "A janela de guia, os passos em andamento e a seta de destino do Guidelime ganham uma linha cada, para você ocultar o guia e manter a seta mostrando o caminho."
L["Hold a key to bring up a wheel of raid markers and put one on your target, or drop a ground marker where you let go. A master wheel opens any of the wheels from one key. Set the keys on the Keybinds page."] = "Segure uma tecla para abrir uma roda de marcas de raide e pôr uma no seu alvo, ou largar uma marca no chão onde você soltar. Uma roda principal abre qualquer uma das rodas com uma tecla só. Defina as teclas na página Atalhos."
L["Hold a key to bring up a wheel of the visions and turn Heal, Quest, Duel or Roll Vision on or off, even in a fight. It's on the master wheel too, and each vision has a toggle key of its own on the Keybinds page."] = "Segure uma tecla para abrir uma roda das Visions e ligar ou desligar Heal, Quest, Duel ou Roll Vision, até em combate. Ela também está na roda principal, e cada Vision tem uma tecla própria de ligar/desligar na página Atalhos."
L["In CineMode the two players in a duel near you get their nameplates, each duel with its own color border and class icons."] = "No CineMode, os dois jogadores num duelo perto de você ganham as placas, cada duelo com uma borda de cor própria e ícones de classe."
L["In a group, a window shows each item being rolled on, with everyone's pick and roll and the winner on top, so you needn't read the rolls in chat. Turn it off in the Visions page."] = "Em grupo, uma janela mostra cada item sendo disputado, com a escolha e a rolagem de todo mundo e o vencedor em cima, para você não precisar ler as rolagens no bate-papo. Desative na página Visions."
L["Instead of damage meter numbers, see your race with #1 (or your lead over #2) as a bar, a race track or a ladder, plus a recap of how you did after each boss and dungeon."] = "Em vez dos números do medidor de dano, veja a sua disputa com o #1 (ou a sua vantagem sobre o #2) como uma barra, uma pista de corrida ou uma escada, mais um resumo de como você foi depois de cada chefe e masmorra."
L["Interface, Camera and Quality of life hold their pages behind a row of icons, with one search box for all of them."] = "Interface, Câmera e Conveniência guardam as páginas atrás de uma fileira de ícones, com uma caixa de busca só para todas."
L["Jade wisps"] = "Lumes de jade"
L["Links to the guidebook, troubleshooting and the bug report form, how to send your log with /cine log, and the Profiler for a slow game, together in Community."] = "Links para o guia, a solução de problemas e o formulário de bugs, como mandar o seu registro com /cine log, e o Profiler para um jogo lento, tudo junto em Comunidade."
L["Lore Forever's subtitles, floating player, new page note and pin card get rows of their own and fade with Cinematic. With Custom dialogue frames on, a Play button on the box with the NPC's words plays the quest's narration or stops it."] = "As legendas, o player flutuante, a nota de página nova e o cartão fixado do Lore Forever ganham linhas próprias e esmaecem com o Cinematic. Com Quadros de diálogo personalizados ativo, um botão Tocar na caixa com as falas do PNJ toca ou para a narração da missão."
L["Make scenes, like dungeons in combat, and pick what each spell shows in each one, side by side in one grid. Tick several spells to set them at once, or copy one spell's row onto others."] = "Crie cenas, como masmorras em combate, e escolha o que cada feitiço mostra em cada uma, lado a lado numa grade só. Marque vários feitiços para ajustar de uma vez, ou copie a linha de um feitiço para outros."
L["Make your own camera scenes on the Scenes page: an emote, a spell, a buff, a place, a moment or a key can start one, and a scene can have several triggers. The built-in ones are grouped by camera and take triggers of yours too. On My Shots, set how a camera sways and zooms, and share either with a friend."] = "Crie as suas próprias cenas de câmera na página Cenas: uma expressão, um feitiço, um bônus, um lugar, um momento ou uma tecla podem iniciar uma, e uma cena pode ter vários gatilhos. As embutidas são agrupadas por câmera e também aceitam gatilhos seus. Em Minhas tomadas, defina como uma câmera balança e dá zoom, e compartilhe qualquer um com um amigo."
L["Marks and colors for your focus, the unit under the mouse and a target that's attacking you, not just your target, each with its own look, when it shows, and rows for just enemies or friends. Set them on the Style hub's Nameplates page."] = "Marcas e cores para o seu foco, a unidade sob o mouse e um alvo que está atacando você, não só o seu alvo, cada um com a aparência própria, quando aparece, e linhas só para inimigos ou amigos. Ajuste na página Placas de identificação do Estilo."
L["Mobs and NPCs you still need for a quest keep their nameplates up, with a golden ! on their plate and your target frame. Optionally, the quest object in front of you glows so it's easy to spot."] = "Inimigos e PNJs de que você ainda precisa para uma missão mantêm as placas à vista, com um ! dourado na placa e no seu quadro de alvo. Se quiser, o objeto de missão na sua frente brilha para ficar fácil de achar."
L["Motes (class and spec)"] = "Partículas (classe e especialização)"
L["Motes of light"] = "Partículas de luz"
L["Nameplates have a hub of their own: which show, the new Icons page for class and role icons, and their looks. Each kind of plate can have its own parts, and each Nameplate Style row its own bar, border, name font and level box."] = "As placas têm uma seção própria: quais aparecem, a nova página Ícones para ícones de classe e função, e a aparência delas. Cada tipo de placa pode ter as suas partes, e cada linha do Estilo das placas a sua barra, borda, fonte do nome e caixa de nível."
L["Names kept up over faded nameplates in CineMode now look like the game's own names over heads: colored by who they are, and smaller further off."] = "Os nomes mantidos sobre as placas esmaecidas no CineMode agora parecem os nomes do próprio jogo sobre as cabeças: coloridos por quem são, e menores mais longe."
L["Naowh Forever's top bar now fades in CineMode (a row on the Addon Frames page), and its RestedXP guide window fades with the Quest tracker row."] = "A barra de cima do Naowh Forever agora esmaece no CineMode (uma linha na página Quadros de addons), e a janela de guia do RestedXP dele esmaece com a linha Rastreador de missões."
L["Pick HD or SD for Cinematic's settings and windows on the main page: flat and dark, or the game's own look. Auto follows your client, and your Character Models setting on WoW Forever."] = "Escolha HD ou SD para as configurações e janelas do Cinematic na página principal: lisas e escuras, ou com a aparência do próprio jogo. Auto segue o seu cliente, e a sua configuração Modelos de personagem no WoW Forever."
L["Pick how much Cinematic does, Subtle, Balanced or Cinema, then Customize changes one part at a time: your layout, camera, look, Visions, chat and sound."] = "Escolha o quanto o Cinematic faz, Sutil, Equilibrado ou Cinema, e depois Personalizar muda uma parte de cada vez: o seu layout, câmera, aparência, Visions, bate-papo e som."
L["Pick which parts of your frame and the target and focus frames show (portrait, name, level, frame art) for you and each kind of unit, to keep just the bars."] = "Escolha quais partes do seu quadro e dos quadros de alvo e foco aparecem (retrato, nome, nível, arte da moldura) para você e cada tipo de unidade, para ficar só com as barras."
L["Plague wisps"] = "Lumes de peste"
L["Pretends you're auto-running: the auto-run camera runs for 30 seconds where you stand. Moving, or clicking Stop, ends it."] = "Finge que você está correndo automaticamente: a câmera de corrida automática roda por 30 segundos onde você está. Se mexer, ou clicar em Parar, encerra."
L["Pretends you're auto-walking: the RP walk camera runs for 30 seconds where you stand. Moving, or clicking Stop, ends it."] = "Finge que você está andando automaticamente: a câmera de passeio RP roda por 30 segundos onde você está. Se mexer, ou clicar em Parar, encerra."
L["Rain"] = "Chuva"
L["Rain, snow and sandstorms have their own page in Atmosphere. Preview each one, and pick its color and how fast it comes in on the Style tab."] = "Chuva, neve e tempestades de areia têm uma página própria em Atmosfera. Veja cada um, e escolha a cor e o quão rápido chega na aba Estilo."
L["Runs Chat Cam for 30 seconds with a made-up conversation between two speakers either side of you. Moving, or clicking Stop, ends it."] = "Roda a Câmera de bate-papo por 30 segundos com uma conversa inventada entre duas pessoas, uma de cada lado seu. Se mexer, ou clicar em Parar, encerra."
L["Runs the quest camera for 30 seconds as if you were talking to a quest giver in front of you. Moving, or clicking Stop, ends it."] = "Roda a câmera de missão por 30 segundos como se você estivesse falando com um PNJ de missão na sua frente. Se mexer, ou clicar em Parar, encerra."
L["Sea breeze"] = "Brisa do mar"
L["See how much of your computer's time Cinematic takes, as a graph of the last five minutes, and record a while of play to see which parts cost the most. If Cinematic feels slow, Copy report and send it to us."] = "Veja quanto do tempo do seu computador o Cinematic gasta, num gráfico dos últimos cinco minutos, e grave um tempo de jogo para ver quais partes pesam mais. Se o Cinematic parecer lento, use Copiar relatório e mande para nós."
L["See your keyboard on screen with what every key does: its spell's icon, cooldown and count, or the command's name. Hold its key to peek, tap it to keep it up, or type /cine keys. Hold Shift, Ctrl or Alt to see those keys."] = "Veja o seu teclado na tela com o que cada tecla faz: o ícone do feitiço, a recarga e a contagem, ou o nome do comando. Segure a tecla dele para espiar, toque para mantê-lo, ou digite /cine keys. Segure Shift, Ctrl ou Alt para ver essas teclas."
L["Share a wheel of yours as a line of text and import one from a friend, reading every command first. Icons now come from every icon the game has, like the macro window's, and you can add icons of your own to the marker and vision wheels."] = "Compartilhe uma roda sua como uma linha de texto e importe uma de um amigo, lendo cada comando antes. Os ícones agora vêm de todos os ícones do jogo, como na janela de macros, e você pode adicionar ícones seus às rodas de marcas e de Visions."
L["Shortly after the death camera starts: YOU DIED across the middle of the screen, \"wasted\" or words of your own. Only with the death camera on (the Die row on the Scenes page)."] = "Logo depois que a câmera de morte começa: VOCÊ MORREU no meio da tela, \"já era\" ou palavras suas. Só com a câmera de morte ligada (a linha Morrer da página Cenas)."
L["Shows a pretend card for each moment in turn (close the settings to see it). With someone targeted it's theirs, and its buttons really emote at them; with no one, they only say in chat what they'd do."] = "Mostra um cartão de mentira para cada momento, um de cada vez (feche as configurações para ver). Com alguém no alvo, é o dele, e os botões fazem a expressão de verdade para ele; sem ninguém, só dizem no bate-papo o que fariam."
L["Six new Vitals Vision themes are built from the game's own full-screen effects, moving and closing in as your health drops: Cosmic void, Hellfire, Radiance, Frostbite, Fel flames and Spellfire. Find them under More themes."] = "Seis temas novos do Vitals Vision feitos com os efeitos de tela cheia do próprio jogo, se movendo e se fechando conforme a sua vida cai: Vazio cósmico, Fogo do Inferno, Radiância, Ulceração, Chamas vis e Fogo Mágico. Ache em Mais temas."
L["Someone from your guild (not in your group) comes into view: with friendly nameplates on, as soon as you see them; otherwise when you mouse over or target them. Once an hour per person."] = "Alguém da sua guilda (fora do seu grupo) aparece: com as placas amigáveis ativas, assim que você vê a pessoa; senão, quando você passa o mouse ou a mira. Uma vez por hora por pessoa."
L["Someone near you earns an achievement (a stranger, someone in your group or in your guild)."] = "Alguém perto de você ganha uma conquista (um desconhecido, alguém do seu grupo ou da sua guilda)."
L["Someone you grouped with lately (the game's Recent Allies, not in your group now) comes into view: with friendly nameplates on, as soon as you see them; otherwise when you mouse over or target them. Once an hour per person."] = "Alguém com quem você jogou em grupo há pouco (os Aliados recentes do jogo, fora do seu grupo agora) aparece: com as placas amigáveis ativas, assim que você vê a pessoa; senão, quando você passa o mouse ou a mira. Uma vez por hora por pessoa."
L["Souls"] = "Almas"
L["Spanish, German, French, Russian, Portuguese, Italian, Korean and Chinese, with a Language choice on the main page."] = "Espanhol, alemão, francês, russo, português, italiano, coreano e chinês, com uma escolha de Idioma na página principal."
L["Starlight"] = "Luz das estrelas"
L["Talking to an NPC, their words show in a speech bubble over their head and your replies in a list below, instead of the game's gossip and quest windows. Pick a reply with 1-9, and Space to read on."] = "Ao falar com um PNJ, as falas dele aparecem num balão sobre a cabeça e as suas respostas numa lista embaixo, em vez das janelas de conversa e de missão do jogo. Escolha uma resposta com 1-9, e Espaço para continuar lendo."
L["The Addon Frames page's Find frames tab can look for other addons' frames that nothing fades, say which addon made each and guess which row it should follow. Add them with a click."] = "A aba Encontrar quadros da página Quadros de addons pode procurar quadros de outros addons que nada esmaece, dizer qual addon fez cada um e adivinhar qual linha ele deve seguir. Adicione com um clique."
L["The Camera hub's General page now shows every camera, built in and yours, as an icon. Click one to open a tab with its script and the scenes that play it, and jump straight to either."] = "A página Geral de Câmera agora mostra cada câmera, embutida ou sua, como um ícone. Clique numa para abrir uma aba com o roteiro dela e as cenas que a tocam, e pular direto para qualquer um."
L["The Cards page has 13 new moments: level up, places discovered, flight arrivals, inns, achievements, reputation, new mounts and pets, profession ranks, story quests, dungeons cleared, rares, battlegrounds and kill streaks. Every card now belongs to one of four looks, so they match out of the box."] = "A página Cartões tem 13 momentos novos: subir de nível, lugares descobertos, chegadas de voo, estalagens, conquistas, reputação, montarias e mascotes novos, níveis de profissão, missões de história, masmorras concluídas, raros, campos de batalha e sequências de abates. Todo cartão agora pertence a uma de quatro aparências, para combinarem logo de cara."
L["The UI fades and letterbox bars come in between fights. Combat, casting and opening windows bring it back."] = "A interface esmaece e as faixas entram entre as lutas. Combate, lançamentos e abrir janelas trazem tudo de volta."
L["The faded minimap comes up when ore, herbs or treasure show on it, a quest of yours is done, or another icon appears, with a ping on the node if you like."] = "O minimapa esmaecido aparece quando minério, ervas ou tesouro surgem nele, uma missão sua fica pronta, ou outro ícone aparece, com um sinal no ponto se você quiser."
L["The first time you enter a zone like Westfall or Duskwood, its name slams onto the screen in huge white capitals. Comes with the new Headline style."] = "Na primeira vez que você entra numa zona como Cerro Oeste ou Floresta do Crepúsculo, o nome dela cai com tudo na tela em letras brancas enormes. Vem com o novo estilo Manchete."
L["The game's floating combat text about you (hits, heals, misses, power, auras, Low Health) now has a page of its own on Style: a look for each kind, beside your character, and it can follow the Shoulder Cam."] = "O texto de combate flutuante do jogo sobre você (golpes, curas, erros, poder, auras, Pouca vida) agora tem uma página própria em Estilo: uma aparência para cada tipo, ao lado do seu personagem, e ele pode seguir a Câmera de ombro."
L["The game's own graphics settings one by one, past what its Graphics menu allows: ground clutter, view distance and more."] = "As configurações gráficas do próprio jogo uma por uma, além do que o menu Gráficos permite: vegetação rasteira, distância de visão e mais."
L["The game's windows open in the middle of the screen, can be dragged by their title bar and open where you last dropped them. The backpack too."] = "As janelas do jogo abrem no meio da tela, podem ser arrastadas pela barra de título e abrem onde você as deixou da última vez. A mochila também."
L["The minimap button glows while a vision is doing something, and its menu lists the visions in use with a link to each one's page."] = "O botão do minimapa brilha enquanto uma Vision está fazendo algo, e o menu dele lista as Visions em uso com um link para a página de cada uma."
L["The names Cinematic draws on faded nameplates in CineMode have a page of their own: their colors, outline, opacity, size and height, with presets and a preview."] = "Os nomes que o Cinematic desenha nas placas esmaecidas no CineMode têm uma página própria: cores, contorno, opacidade, tamanho e altura, com predefinições e pré-visualização."
L["The rule editor is rebuilt: words in categories you can search, suggestions as you type, and a line that shows which parts of your rule are true where you stand."] = "O editor de regras foi refeito: palavras em categorias que você pode procurar, sugestões enquanto digita, e uma linha que mostra quais partes da sua regra são verdadeiras onde você está."
L["Three new cards in the top bar: how much of a zone you've explored, an achievement with one step left, and an achievement's step done. Each shows at most once every 10 minutes; on in the Cinema profile."] = "Três cartões novos na barra de cima: quanto de uma zona você explorou, uma conquista com um passo faltando, e um passo de conquista concluído. Cada um aparece no máximo uma vez a cada 10 minutos; ativos no perfil Cinema."
L["Tick Copy chat button on the Quality of life page and a small icon in a chat window's corner opens its lines, ready to select and copy with Ctrl+C."] = "Marque Botão Copiar bate-papo na página Conveniência e um iconezinho no canto de uma janela de bate-papo abre as linhas dela, prontas para selecionar e copiar com Ctrl+C."
L["Tick Show speech from behind you on the Chat page and says and yells from people behind you or out of view show as bubbles low on the screen, rising up from below, instead of bringing up chat."] = "Marque Mostrar falas vindas de trás de você na página Bate-papo e o que as pessoas atrás de você ou fora de vista dizem e gritam aparece como balões embaixo na tela, subindo de baixo, em vez de abrir o bate-papo."
L["Type /cine find and a few words, or search in the settings, to get a list of every matching option; click one to go straight to it."] = "Digite /cine find e algumas palavras, ou procure nas configurações, para ter uma lista de todas as opções que batem; clique numa para ir direto a ela."
L["Type /cine why, or pick it from the minimap button's menu, then click any frame to see why it's showing or hidden right now and which settings say so. It works on other addons' frames, Cinematic's own (like quest talk), and the last tooltip too. The Why Is It Showing? page in Community lists every row of frames at once."] = "Digite /cine why, ou escolha no menu do botão do minimapa, depois clique em qualquer quadro para ver por que ele está aparecendo ou oculto agora e quais configurações dizem isso. Funciona nos quadros de outros addons, nos do próprio Cinematic (como a conversa de missão) e na última dica também. A página Por que está aparecendo? em Comunidade lista todas as linhas de quadros de uma vez."
L["Type part of a frame's name, or of the addon that made it, to find frames to fade. Hover a match to see it marked on screen, then click it to fade it."] = "Digite parte do nome de um quadro, ou do addon que o fez, para achar quadros para esmaecer. Passe o mouse num resultado para vê-lo marcado na tela, depois clique para esmaecê-lo."
L["Valhalla"] = "Valhalla"
L["Venom wisps"] = "Lumes de veneno"
L["Vitals Vision's themes now have spiral arms turning over the screen as your health drops, quicker the weaker you are. Set them on the Style page's new Swirl tab, or try the swirl themes under More themes: Vortex, Abyss and Dungeon portal."] = "Os temas do Vitals Vision agora têm braços em espiral girando pela tela conforme a sua vida cai, mais rápido quanto mais fraco você está. Ajuste na nova aba Redemoinho da página Estilo, ou experimente os temas de redemoinho em Mais temas: Vórtice, Abismo e Portal de masmorra."
L["Weather on the screen"] = "Clima na tela"
L["Weather page"] = "Página Clima"
L["Wheels of your own, up to 8: each icon on one runs a command when you pick it, such as /rw Pull in 10 or /readycheck (anything a macro can do, a line each), in a fight too. Give a wheel its own key here, or put it on the master wheel. They're the same for all your characters."] = "Rodas suas, até 8: cada ícone numa delas roda um comando quando você o escolhe, como /rw Pull em 10 ou /readycheck (qualquer coisa que um macro faz, uma linha cada), até em combate. Dê a uma roda uma tecla própria aqui, ou ponha na roda principal. São iguais para todos os seus personagens."
L["When someone buffs you, raises you, emotes at you, summons you or trades with you, or your group kills a boss or levels up, a small card shows who it was, with emotes to answer in one click. Pick each moment's emotes (voice ones too) and one of six card styles."] = "Quando alguém dá um bônus em você, ressuscita você, faz uma expressão para você, invoca você ou negocia com você, ou o seu grupo mata um chefe ou sobe de nível, um cartãozinho mostra quem foi, com expressões para responder num clique. Escolha as expressões de cada momento (as de voz também) e um de seis estilos de cartão."
L["When the LocalDefense channel says a place is under attack (\"Dun Algaz is under attack!\"), with your faction's city bell. The same place at most once every 90 seconds."] = "Quando o canal DefesaLocal diz que um lugar está sob ataque (\"Dun Algaz está sob ataque!\"), com o sino da cidade da sua facção. O mesmo lugar no máximo uma vez a cada 90 segundos."
L["When the time of day changes during play (not in combat), its name with a fitting sound: a rooster at dawn, a horse in the morning, your faction's bell at midday, frogs in the evening, an owl at dusk and a wolf at night."] = "Quando a hora do dia muda durante o jogo (fora de combate), o nome dela com um som que combina: um galo ao amanhecer, um cavalo de manhã, o sino da sua facção ao meio-dia, sapos à tardinha, uma coruja ao anoitecer e um lobo à noite."
L["Wisps"] = "Lumes"
L["Wisps (class and spec)"] = "Lumes (classe e especialização)"
L["You and a stranger (not in your group or guild) target each other for 10 seconds straight. Once you've looked away, it can happen again."] = "Você e um desconhecido (fora do seu grupo ou guilda) miram um ao outro por 10 segundos seguidos. Depois que você desvia o olhar, pode acontecer de novo."
L["Your character lies down as if dead and the death camera runs for 30 seconds. Moving, or clicking Stop, ends it."] = "O seu personagem deita como se estivesse morto e a câmera de morte roda por 30 segundos. Se mexer, ou clicar em Parar, encerra."
L["Your player frame, pet frame and resource display have a page of their own: kept up while you recover or run low on mana, and held back at the start of a fight until your power changes."] = "O seu quadro de jogador, o quadro do ajudante e a exibição de recursos têm uma página própria: ficam à vista enquanto você se recupera ou está com pouca mana, e esperam no começo de uma luta até o seu poder mudar."
L["\"Dun Algaz is under attack!\" shows in red where the zone name appears, with your faction's city bell."] = "\"Dun Algaz está sob ataque!\" aparece em vermelho onde o nome da zona aparece, com o sino da cidade da sua facção."
